export default function ToggleButtonDemo() {
  const [selected, setSelected] = React.useState(false);

  return (
    <ToggleButton
      size="small"
      value="check"
      selected={selected}
      onChange={() => {
        setSelected(!selected);
      }}
    >
      <FormatAlignLeft />
    </ToggleButton>
  );
}

