components.description:
import TextField from '@mui/material/TextField';
import Autocomplete from '@mui/material/Autocomplete';

export default function ComboBox() {
  return (
    <Autocomplete
      defaultValue={[options[0]]}
      getOptionLabel={(option) => option}
      id='multiple-values-demo'
      multiple
      options={options}
      sx={{ width: 300 }}
      renderInput={(params) => (
        <TextField {...params} label='Options' placeholder='Select option' />
      )}
    />
  );
}

const options = ['Option 1', 'Option 2', 'Option 3'];

components.description_rt:
import TextField from &#39;@mui/material/TextField&#39;;
import Autocomplete from &#39;@mui/material/Autocomplete&#39;;

export default function ComboBox() {
  return (
    &lt;Autocomplete
      defaultValue={[options[0]]}
      getOptionLabel={(option) =&gt; option}
      id=&#39;multiple-values-demo&#39;
      multiple
      options={options}
      sx={{ width: 300 }}
      renderInput={(params) =&gt; (
        &lt;TextField {...params} label=&#39;Options&#39; placeholder=&#39;Select option&#39; /&gt;
      )}
    /&gt;
  );
}

const options = [&#39;Option 1&#39;, &#39;Option 2&#39;, &#39;Option 3&#39;];

